"""One bounded model invocation per process; requests are generated by the trusted server adapter."""

import json
from pathlib import Path
import sys
import time

from media_tag.storage.filesystem import FilesystemBackend
from .contracts import CLIPOptions, DiagnosticCandidate, FaceOptions, FrameInput, ModelFailure, OCROptions
from .native import prepare_native_runtime
from .registry import ModelRegistry
from .calibration import candidate_fingerprint, rank
from .runtime import PREPROCESS_VERSION


def execute(request):
    from PIL import Image
    prepare_native_runtime()
    import psutil
    from .inference import OCRModel, FaceModel, CLIPModel
    registry = ModelRegistry(Path(request['model_root']))
    if registry.revision != request['model_revision']:
        raise ModelFailure('model_revision_mismatch')
    kind = request['kind']
    option_type = {'ocr': OCROptions, 'face': FaceOptions, 'clip': CLIPOptions}.get(kind)
    if option_type is None:
        raise ModelFailure('stage_unavailable')
    options = option_type.model_validate_json(json.dumps(request['options']))
    if not request['frames'] or len(request['frames']) > options.max_frames:
        raise ModelFailure('frame_budget')
    workspace = FilesystemBackend(Path(request['workspace']))
    candidates = tuple(DiagnosticCandidate.model_validate_json(json.dumps(v)) for v in request.get('diagnostic_candidates', []))
    if candidates and not request.get('diagnostic_only', False):
        raise ModelFailure('unpublished_vocabulary')
    started = time.monotonic()
    model = {'ocr': OCRModel, 'face': FaceModel, 'clip': CLIPModel}[kind](registry, **({'device': request['device']} if kind == 'clip' else {}))
    reports = []
    for raw_frame in request['frames']:
        frame = FrameInput.model_validate_json(json.dumps(raw_frame))
        artifact = frame.artifact
        if frame.source_sha256 != request['source_sha256']:
            raise ModelFailure('source_hash_mismatch')
        with workspace.open_read(artifact.ref) as stream:
            from hashlib import sha256
            raw = stream.read(16 * 1024**2 + 1)
            if len(raw) > 16 * 1024**2 or sha256(raw).hexdigest() != artifact.sha256:
                raise ModelFailure('frame_integrity')
            stream.seek(0)
            with Image.open(stream) as image:
                if image.format != 'PNG' or image.width * image.height > options.max_pixels:
                    raise ModelFailure('pixel_budget')
                image = image.convert('RGB')
                output = model.infer(image, texts=tuple(v.text for v in candidates)) if kind == 'clip' else model.infer(image, options)
                if kind == 'clip':
                    fingerprint = candidate_fingerprint(candidates, model_revision=registry.revision, preprocess_version=PREPROCESS_VERSION)
                    output['candidate_fingerprint'] = fingerprint
                    output['field_candidates'] = rank(output['cosine_scores'], candidates, top_k=options.top_k, fingerprint=fingerprint)
                reports.append({'artifact': artifact.model_dump(), 'normalized_seconds': frame.normalized_seconds,
                                'width': image.width, 'height': image.height, 'observation': output})
    memory = psutil.Process().memory_info()
    return {'kind': kind, 'model_revision': registry.revision, 'frames': reports, 'source_sha256': request['source_sha256'],
            'full_video_observed': False, 'continuous_observation': False, 'identity_inference': False,
            'medical_confirmation': False, 'privacy_confirmation': False, 'effective_values_written': False,
            'elapsed_seconds': time.monotonic() - started, 'peak_process_bytes': getattr(memory, 'peak_wset', memory.rss),
            'candidate_state': 'diagnostic_only' if candidates else 'missing_published_vocabulary' if kind == 'clip' else 'not_applicable'}


def main(argv=None):
    arguments = sys.argv[1:] if argv is None else argv
    if len(arguments) != 2:
        return 2
    request_path, response_path = map(Path, arguments)
    try:
        request = json.loads(request_path.read_text(encoding='utf-8'))
        if 'executor_pid' in request:
            from .lifecycle import watch_parent
            watch_parent(request['executor_pid'])
        result = {'ok': True, 'data': execute(request)}
    except BaseException as exc:
        if isinstance(exc, (KeyboardInterrupt, SystemExit)):
            raise
        code = exc.code if isinstance(exc, ModelFailure) else 'oom' if type(exc).__name__ in ('OutOfMemoryError', 'CUDAOutOfMemoryError') else 'model_execution_failed'
        result = {'ok': False, 'error_code': code}
    response_path.write_text(json.dumps(result, allow_nan=False, sort_keys=True), encoding='utf-8')
    return 0 if result['ok'] else 2


if __name__ == '__main__':
    raise SystemExit(main())
